'use strict';
let dailySymbolFilter='';
let dailyBusy=false,dailyEditions=[],dailyLimit=12;
const articleMetrics=new Map();
function articlePerformanceHTML(a){const p=articleMetrics.get(a.id);return `<div class="article-performance" data-performance="${esc(a.id||'')}"><b>Since publication · hypothetical long</b>${p?.rows?.length?p.rows.map(r=>`<div class="article-return"><button data-ticker="${esc(r.symbol)}">${esc(r.symbol)}</button><strong class="${r.return===undefined?'muted':r.return>=0?'gain':'loss'}">${r.return===undefined?'—':signed(r.return)}</strong><small>${r.return===undefined?esc(r.status):`Entry close ${date(r.entry)} · latest ${date(r.asOf)}${r.stale?' · stale':''}`}</small></div><details><summary>Benchmark & risk</summary><p>${r.excess==null?'SPY comparison unavailable':'vs SPY '+(r.excess>=0?'+':'')+r.excess.toFixed(2)+' pp'+(r.benchmarkStale?' · benchmark stale':'')} · ${r.drawdown==null?'Drawdown unavailable':'Max closing drawdown '+signed(r.drawdown)}</p><p>${(r.forward||[]).map(x=>x.sessions+'d: '+(x.return==null?'pending':signed(x.return))).join(' · ')}</p>${r.entryPrice?`<p>Entry ${money(r.entryPrice,r.currency)} → latest ${money(r.latest,r.currency)}</p>`:''}</details>`).join(''):`<small>${p?.error?'Performance unavailable; retry on refresh':a.tickers.length?'Loading closing prices…':'No stock identified; return unavailable'}</small>`}</div>`}
function dailyArticlesHTML(editions){const articles=editions.flatMap(e=>e.articles.filter(a=>a.format===2&&(!dailySymbolFilter||a.tickers.includes(dailySymbolFilter))).map(a=>({...a,editionDate:e.date})));return articles.slice(0,dailyLimit).map(a=>{const review=a.reviews?.at(-1);return `<article class="daily-article"><div class="daily-tickers">${a.tickers.map(t=>`<button data-ticker="${esc(t)}">${esc(t)}</button>`).join('')}<small>Published ${a.publishedAt?esc(stamp(a.publishedAt)):a.editionDate?date(a.editionDate):'Time unknown'}</small></div><h3>${esc(a.title)}</h3><p class="daily-tldr">${esc(a.tldr)}</p><p class="daily-bottom"><b>Watch:</b> ${esc(a.watch)} <b>Invalidated if:</b> ${esc(a.invalidation)}</p><div class="daily-sources">${a.sources.map((u,i)=>researchLink(u,'Source '+(i+1))).join(' · ')}</div><small class="muted">${esc(a.horizon)} · Research hypothesis</small>${a.tickers[0]?`<button class="map-open" data-map="${esc(a.tickers[0])}" data-thesis="${esc(a.id||'')}">Explore connections ↗</button>`:''}${typeof decisionPlanHTML==='function'?decisionPlanHTML(a):''}${articlePerformanceHTML(a)}${review?`<details class="thesis-review"><summary>Research review: ${esc(review.verdict)} · ${date(review.reviewedAt.slice(0,10))}</summary><p>${esc(review.summary)}</p>${review.sources.map((s,i)=>researchLink(s,'Evidence '+(i+1))).join(' · ')}</details>`:'<small class="muted">Follow-up review pending</small>'}</article>`}).join('')+(articles.length>dailyLimit?'<button id="dailyMore" class="secondary">Load older theses</button>':'')||`<p class="empty">${dailySymbolFilter?'No published research mentions '+esc(dailySymbolFilter)+' yet. Open its map for disclosed trades and source evidence.':'No connection has passed the research checks yet. Explore the map for disclosed trades, source records and research leads.'}</p>`}
async function fillArticlePerformance(){const articles=dailyEditions.flatMap(e=>e.articles).filter(a=>a.format===2).slice(0,dailyLimit);for(let i=0;i<articles.length;i+=3)await Promise.all(articles.slice(i,i+3).map(async a=>{if(!a.id)return;try{articleMetrics.set(a.id,await getLiveJSON('/api/research/performance?id='+a.id))}catch{articleMetrics.set(a.id,{error:true})}const el=document.querySelector('[data-performance="'+a.id+'"]');if(el)el.outerHTML=articlePerformanceHTML(a)}))}
async function loadDailyResearch(){if(dailyBusy)return;dailyBusy=true;try{const r=await getLiveJSON('/api/research/daily');dailyEditions=r.editions||[];$('#dailyArticles').innerHTML=dailyArticlesHTML(dailyEditions);const overdue=r.lastAttempt&&Date.now()-Date.parse(r.lastAttempt)>36*3600000;$('#dailyStatus').textContent=(overdue?'Research overdue · ':'')+(r.status||'Daily research')+(r.lastAttempt?' · Checked '+stamp(r.lastAttempt):'')+' · Daily, 08:00 Paris'+(r.reviewer?' · Follow-up: '+r.reviewer.status:'');await fillArticlePerformance()}catch{$('#dailyStatus').textContent='Daily research unavailable; retry shortly. Previously loaded briefs remain visible.'}finally{dailyBusy=false}}
if(typeof window!=='undefined'){$('#dailyRefresh').onclick=loadDailyResearch;document.addEventListener('click',e=>{if(e.target.id==='dailyMore'){dailyLimit+=12;$('#dailyArticles').innerHTML=dailyArticlesHTML(dailyEditions);fillArticlePerformance()}});setInterval(()=>{if(!document.hidden&&view==='daily')loadDailyResearch()},15*60000)}
